package main

import (
	"fmt"
)

func twoSum(nums []int, target int) []int {
	numIndex := make(map[int]int)
	for i, num := range nums {
		diff := target - num 
		if idx, found := numIndex[diff]; found {
			// Sorting the indices so the smaller one outputs first
			if idx < i {
				return []int{idx, i}
			}
			return []int{i, idx}
		}
		numIndex[num] = i
	}
	return nil
}

func main() {
	var target, n int

	// 1. Read target and array size N
	fmt.Scan(&target)
	fmt.Scan(&n)

	// 2. Read the N space-separated integers into a slice
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&nums[i])
	}

	// 3. Solve and print the results
	result := twoSum(nums, target)
	if result != nil {
		fmt.Printf("%d %d\n", result[0], result[1])
	}
}
